    res.json({ paymentUrl: response.data.payment_url });
  } catch (err) {
    console.error('PayGate API hiba:', err.response?.data || err.message);
    res.status(500).json({ error: 'Fizetési hiba' });
  }
});

// Indítsd a szervert
const PORT = process.env.PORT || 3001;
app.listen(PORT, () => {
  console.log(`Backend fut a ${PORT}-es porton`);
});
```
**Fontos:** A pontos paramétereket mindig a PayGate.to API dokumentációja alapján töltsd ki!

